-- Framework FPSI v2 lean — substitui catálogo framework 27×210 no remoto
-- Controles ativos: 1001–1017. Remove 1018–1027 e medidas 10001–10210 legadas.

DELETE FROM public.programa_controle pc
WHERE pc.controle IN (
  SELECT id FROM public.controle WHERE pack_id = 'framework' AND id BETWEEN 1018 AND 1027
);
-- programa_medida: migrar antes com scripts/repair-framework-v2-linkages.mjs
DELETE FROM public.medida WHERE pack_id = 'framework' AND id BETWEEN 10103 AND 10210;
DELETE FROM public.controle WHERE pack_id = 'framework' AND id BETWEEN 1018 AND 1027;



UPDATE public.content_pack SET versao = '2.0.0', descricao = 'Catálogo enxuto FPSI (17 controles, 102 medidas)' WHERE id = 'framework';
